INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '预包装食品标签可以暗示性的语言、图形、符号，使消费者将购买的食品或食品的某一性质与另一产品混淆。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品安全总监、食品安全员应当按照岗位职责协助企业主要负责人做好食品安全管理工作。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '营养成分表是标有食品营养成分名称和含量的表格，表格中可以标示的营养成分包括能量、营养素和膳食纤维等。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
