INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品经营者采购预包装食品应当查验其包装上是否有标签，采购散装食品则无需查验。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '《中华人民共和国食品安全法实施条例》规定了食品安全监管部门和公安机关的协作机制，明确行政拘留与其他行政处罚的衔接程序。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '制定食品安全标准，应当以保障公众身体健康为宗旨，做到科学合理、安全可靠。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品生产经营者要依法履行食品安全第一责任人的义务，深入查找不合格食品产生的原因。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', NULL, '否', NULL, '实行统一配送销售方式的食用农产品销售企业，不可以由企业总部统一建立进货查验记录制度。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '对因标签、标识或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '食品生产经营者主动采取停止生产经营、召回和处置不安全食品措施，消除或者减轻危害后果的，依法从轻或者减轻处罚；违法情节轻微并及时纠正，没有造成危害后果的，不予行政处罚。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品生产经营企业主要负责人是指在本企业生产经营中承担全面领导责任的法定代表人、实际控制人等主要决策人。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品销售场所应布局合理，食品销售场所与食品贮存场所不能设在同一场所内。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '为谋取不当利益，故意向原料或食品中添加非食用物质，故意超范围、超限量使用农药、兽药和食品添加剂，故意使用回收食品，或采用其他不适合人类食用的方法生产加工食品的行为，属于非传统风险。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
